def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    last_me, last_op = history[-1]

    opp_c = 0
    my_d = 0
    unprov_d = 0
    for i in range(n):
        m, o = history[i]
        if o == 'C':
            opp_c += 1
        if m == 'D':
            my_d += 1
        if o == 'D':
            if i == 0 or history[i - 1][0] == 'C':
                unprov_d += 1

    opp_d = n - opp_c

    recent_len = 8 if n >= 8 else n
    recent_opp_d = 0
    recent_my_d = 0
    for i in range(n - recent_len, n):
        m, o = history[i]
        if o == 'D':
            recent_opp_d += 1
        if m == 'D':
            recent_my_d += 1

    opp_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_streak += 1
        else:
            break

    # If the opponent has never defected, try a limited one-time probe.
    # After a non-punishing response, exploit unconditional cooperation.
    if opp_d == 0 and n >= 25:
        if my_d == 0:
            if rng.random() < 0.05:
                return 'D'
            return 'C'
        if my_d == 1 and last_me == 'D':
            return 'C'
        return 'D'

    if last_op == 'D':
        # Their last D was likely a direct retaliation for our previous D.
        provoked = n >= 2 and history[-2][0] == 'D'

        # Restore cooperation after short provoked retaliation against
        # opponents that are mostly cooperative and rarely unprovoked.
        if provoked and opp_c * 2 >= n and unprov_d <= 2 and recent_opp_d <= 2:
            return 'C'

        # Break longer provoked feuds with cooperative opponents.
        if provoked and opp_c * 2 >= n and unprov_d <= max(2, n // 10) and recent_my_d >= 2:
            return 'C' if rng.random() < 0.6 else 'D'

        # Occasional olive branch during long conflicts against nice opponents.
        if opp_streak >= 3 and opp_c * 3 >= n * 2 and rng.random() < 0.15:
            return 'C'

        return 'D'

    # Last opponent move was C.  Cooperate unless they have clearly been
    # destructive or unprovoked.
    if opp_c * 5 <= n * 2 and unprov_d >= 3:
        return 'D'
    if recent_opp_d >= 6 and unprov_d >= 2:
        return 'D'

    return 'C'
